### Step 1 – add the API route

1. **Create the file** `app/api/download-data/route.ts` (Lovable projects use the `app/api/...` folder).

```ts
// app/api/download-data/route.ts
import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { Json } from "@supabase/supabase-js";

const SUPABASE_URL = process.env.SUPABASE_URL!;
const SUPABASE_SERVICE_ROLE = process.env.SUPABASE_SERVICE_ROLE!;

// Supabase client with a service‑role key (kept in the server’s Secrets)
const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE, {
  auth: { persistToken: false },
});

export async function GET(req: NextRequest) {
  // Grab the JWT the browser sent automatically
  const authHeader = req.headers.get("Authorization");
  if (!authHeader) return NextResponse.json({ error: "No auth" }, { status: 401 });

  const token = authHeader.replace(/^Bearer\s+/i, "");

  // Verify the token and get the user id
  const { data: session, error } = await supabase.auth.getUser(token);
  if (error || !session?.user?.id) {
    return NextResponse.json({ error: "Invalid token" }, { status: 401 });
  }
  const userId = session.user.id;

  // List tables we want to export – adjust if you have more
  const tables = ["profile", "orders", "messages"]; // ← add yours

  const records: Record<string, Json[]> = {};

  for (const table of tables) {
    const { data, error } = await supabase
      .from(table)
      .select()
      .eq("user_id", userId);
    if (error) return NextResponse.json({ error }, { status: 500 });
    records[table] = data ?? [];
  }

  // Convert to JSON string
  const json = JSON.stringify(records, null, 2);

  // Return as a file
  return new NextResponse(json, {
    status: 200,
    headers: {
      "Content-Type": "application/json",
      "Content-Disposition": `attachment; filename="my-data-${userId}.json"`,
    },
  });
}
```

2. **Add the secrets**  
   - In Lovable, go to **Settings → Secrets** and set:
     - `SUPABASE_URL` – your Supabase project URL
     - `SUPABASE_SERVICE_ROLE` – your Supabase **service‑role** key (not the anon key)

> **Why a service‑role key?**  
> The API runs on the server, so it can read every row that matches the user_id without giving that key to the browser.  

3. **Save point** – commit the new folder (`app/api/download-data`) with a message like “Add download‑data API”.

